    .param .u64 p_weight,
    .param .u64 p_output,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pDin,
    .param .u32 pHin,
    .param .u32 pWin,
    .param .u32 pKd,
    .param .u32 pKh,
    .param .u32 pKw,
    .param .u32 pDout,
    .param .u32 pHout,
    .param .u32 pWout
)
{
    .reg .pred  %p<32>;
    .reg .b32   %r<140>;
    .reg .b64   %rd<80>;
    .reg .f32   %f<10>;
    // Load params
    ld.param.u64    %rd10, [p_input];
    ld.param.u64    %rd11, [p_weight];
    ld.param.u64    %rd12, [p_output];
    ld.param.u32    %r10, [pN];
    ld.param.u32    %r11, [pCin];
    ld.param.u32    %r12, [pCout];
    ld.param.u32    %r13, [pDin];
    ld.param.u32    %r14, [pHin];
    ld.param.u32    %r15, [pWin];
    ld.param.u32    %r16, [pKd];
    ld.param.u32    %r17, [pKh];
    ld.param.u32    %r18, [pKw];
    ld.param.u32    %r19, [pDout];
    ld.param.u32    %r20, [pHout];
    ld.param.u32    %r21, [pWout];
    // Thread/block info
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %ntid.x;
    mov.u32         %r32, %ctaid.x;
    // gid = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32      %r33, %r32, %r31, %r30;
    // total = N * Cout * Dout * Hout * Wout
    mul.lo.u32      %r40, %r10, %r12;      // N*Cout
    mul.lo.u32      %r41, %r19, %r20;      // Dout*Hout
    mul.lo.u32      %r42, %r41, %r21;      // Dout*Hout*Wout
    mul.lo.u32      %r43, %r40, %r42;      // total
    add.u32         %r44, %r43, 0xffffffff; // total-1
    // Active predicate: gid < total
    setp.lt.u32     %p0, %r33, %r43;
    // Block base gid and last gid in block (clamped)
    mul.lo.u32      %r70, %r32, %r31;      // block_base = ctaid.x * ntid.x
    add.u32         %r71, %r70, %r31;      // base + blockDim
    add.u32         %r71, %r71, 0xffffffff; // -1 => last index (unclamped)
    setp.gt.u32     %p1, %r71, %r44;
    selp.u32        %r72, %r71, %r44, %p1; // gid_last = min(last, total-1)
    // Derive oc0 for this CTA from block_base and spatial, and set oc_next=(oc0+1)%Cout
    // oc0 = ((block_base / spatial) % Cout)
    div.u32         %r102, %r70, %r42;    // n*Cout + oc0
    rem.u32         %r76, %r102, %r12;    // oc0
    // oc_next = (oc0 + 1) % Cout
    add.u32         %r80, %r76, 1;
    setp.eq.u32     %p19, %r80, %r12;
    selp.u32        %r80, 0, %r80, %p19;  // oc_next
    // Note: We intentionally do not derive oc_next from gid_last to avoid CTA seam bugs
    // Bank0 will hold oc0 weights; Bank1 will hold oc_next weights
    // r76: oc0, r80: oc_next
    // r42: spatial = Dout*Hout*Wout, r70: block_base = ctaid.x * ntid.x
    // The remainder of the kernel uses r76/r80 for bank selection and loads
    // End oc computation fix
    // K dims
    mul.lo.u32      %r81, %r17, %r18;      // Kh*Kw
    mul.lo.u32      %r82, %r16, %r81;      // K = Kd*Kh*Kw
    // Shared memory base and offsets for two oc's
    mov.u64         %rd40, smem;              // base
    mul.wide.u32    %rd41, %r82, 4;        // K * 4
    add.s64         %rd42, %rd40, 0;       // base0
    add.s64         %rd43, %rd40, %rd41;   // base1
    // Thread-specific decode for active threads
    // We will compute only when active
    @%p0 bra        L_decode_active;
    // If inactive, zero out output ptr to avoid accidental use
    mov.u32         %r50, 0;   // xo
    mov.u32         %r52, 0;   // yo
    mov.u32         %r54, 0;   // zo
    mov.u32         %r56, 0;   // oc
    mov.u32         %r57, 0;   // n
    mov.u64         %rd21, 0;  // out addr
    bra             L_decode_done;
L_decode_active:
    // Decode gid into (xo, yo, zo, oc, n)
    rem.u32         %r50, %r33, %r21;      // xo
    div.u32         %r51, %r33, %r21;      // t1
    rem.u32         %r52, %r51, %r20;      // yo
    div.u32         %r53, %r51, %r20;      // t2
    rem.u32         %r54, %r53, %r19;      // zo
    div.u32         %r55, %r53, %r19;      // t3
    rem.u32         %r56, %r55, %r12;      // oc
    div.u32         %r57, %r55, %r12;      // n
    // Prepare output address: out_ptr + gid * 4
    mul.wide.u32    %rd20, %r33, 4;
    add.s64         %rd21, %rd12, %rd20;
L_decode_done:
    // Select per-thread weight base (based on oc)
    setp.eq.u32     %p2, %r56, %r76;       // oc == oc0 ?
    selp.b64        %rd50, %rd42, %rd43, %p2; // rd50 = base for this thread
    // Accumulator
    mov.f32         %f0, 0f00000000;
    // ic loop
    mov.u32         %r60, 0;               // ic = 0
L_ic:
    setp.ge.u32     %p3, %r60, %r11;
    @%p3 bra        L_ic_end;
    // Cooperative load of weights for oc0 and oc1 into shared memory
    mov.u32         %r83, %r30;            // load_idx = threadIdx.x
L_wload:
    setp.ge.u32     %p4, %r83, %r82;
    @%p4 bra        L_wload_end;
    // Decompose load_idx -> (kz, ky, kx)
    // kz = load_idx / (Kh*Kw)
    div.u32         %r84, %r83, %r81;          // kz
    mul.lo.u32      %r85, %r84, %r81;
    sub.u32         %r86, %r83, %r85;          // rem = load_idx - kz*(Kh*Kw)
    // ky = rem / Kw
    div.u32         %r87, %r86, %r18;          // ky
    mul.lo.u32      %r88, %r87, %r18;
    sub.u32         %r89, %r86, %r88;          // kx
      // Use non-flipped kernel indices (PyTorch cross-correlation)
      // Compute weight index for oc0: ((((ic*Cout + oc0)*Kd + kz)*Kh + ky)*Kw + kx)
      mul.lo.u32      %r90, %r60, %r12;
      add.u32         %r90, %r90, %r76;          // + oc0
      mad.lo.u32      %r90, %r90, %r16, %r84;    // *Kd + kz
      mad.lo.u32      %r90, %r90, %r17, %r87;    // *Kh + ky
      mad.lo.u32      %r90, %r90, %r18, %r89;    // *Kw + kx
     mul.wide.u32    %rd44, %r90, 4;
     add.s64         %rd45, %rd11, %rd44;
     ld.global.f32   %f1, [%rd45];
     // Store to shared[base0 + load_idx*4]
     mul.wide.u32    %rd46, %r83, 4;
     add.s64         %rd47, %rd42, %rd46;
     st.shared.f32   [%rd47], %f1;
      // Compute weight index for oc1 (no spatial flip)
      mul.lo.u32      %r91, %r60, %r12;
      add.u32         %r91, %r91, %r80;          // + oc1
      mad.lo.u32      %r91, %r91, %r16, %r84;    // *Kd + kz
      mad.lo.u32      %r91, %r91, %r17, %r87;    // *Kh + ky
      mad.lo.u32      %r91, %r91, %r18, %r89;    // *Kw + kx
      mul.wide.u32    %rd48, %r91, 4;
     add.s64         %rd49, %rd11, %rd48;
     ld.global.f32   %f2, [%rd49];
     // Store to shared[base1 + load_idx*4]
     add.s64         %rd52, %rd43, %rd46;
     st.shared.f32   [%rd52], %f2;
    // Next index
    add.u32         %r83, %r83, %r31;
    bra             L_wload;
L_wload_end:
    // Ensure all weights are in shared memory
    bar.sync 0;
    // Only active threads perform accumulation
    @!%p0 bra       L_after_compute;
    // Loop over kz
    mov.u32         %r61, 0;               // kz = 0
L_kz:
    setp.ge.u32     %p5, %r61, %r16;
    @%p5 bra        L_kz_end;
    // zi = zo - kz
    sub.s32         %r62, %r54, %r61;
    setp.lt.s32     %p6, %r62, 0;
    setp.ge.s32     %p7, %r62, %r13;
    or.pred         %p8, %p6, %p7;
    @%p8 bra        L_kz_next;
    // Loop over ky
    mov.u32         %r63, 0;               // ky = 0
L_ky:
    setp.ge.u32     %p9, %r63, %r17;
    @%p9 bra        L_ky_end;
    // yi = yo - ky
    sub.s32         %r64, %r52, %r63;
    setp.lt.s32     %p10, %r64, 0;
    setp.ge.s32     %p11, %r64, %r14;
    or.pred         %p12, %p10, %p11;
    @%p12 bra       L_ky_next;
    // Loop over kx
    mov.u32         %r65, 0;               // kx = 0
L_kx:
    setp.ge.u32     %p13, %r65, %r18;
    @%p13 bra       L_kx_end;
    // xi = xo - kx
    sub.s32         %r66, %r50, %r65;
    setp.lt.s32     %p14, %r66, 0;
    setp.ge.s32     %p15, %r66, %r15;
    or.pred         %p16, %p14, %p15;
    @%p16 bra       L_kx_next;
    // Compute input index: (((((n*Cin + ic)*Din + zi)*Hin + yi)*Win + xi))
    mul.lo.u32      %r100, %r57, %r11;     // n*Cin
    add.u32         %r100, %r100, %r60;    // + ic
    mad.lo.u32      %r100, %r100, %r13, %r62; // *Din + zi
    mad.lo.u32      %r100, %r100, %r14, %r64; // *Hin + yi
    mad.lo.u32      %r100, %r100, %r15, %r66; // *Win + xi
    // Load input
    mul.wide.u32    %rd60, %r100, 4;
    add.s64         %rd61, %rd10, %rd60;
    ld.global.f32   %f3, [%rd61];
    // Load weight from shared memory for this (kz,ky,kx)
    // kidx = kz*(Kh*Kw) + ky*Kw + kx
    mul.lo.u32      %r101, %r61, %r81;     // kz*(Kh*Kw)
    mad.lo.u32      %r101, %r63, %r18, %r101; // + ky*Kw
    add.u32         %r101, %r101, %r65;    // + kx
    mul.wide.u32    %rd62, %r101, 4;
    add.s64         %rd63, %rd50, %rd62;
    ld.shared.f32   %f4, [%rd63];
    // FMA accumulate
    fma.rn.f32      %f0, %f3, %f4, %f0;
L_kx_next:
    add.u32         %r65, %r65, 1;
    bra             L_kx;
L_kx_end:
L_ky_next:
    add.u32         %r63, %r63, 1;
    bra             L_ky;
L_ky_end:
L_kz_next:
    add.u32         %r61, %r61, 1;
    bra             L_kz;
L_kz_end:
L_after_compute:
    // Ensure all threads done using shared weights before next ic
    bar.sync 0;
    // Next ic
    add.u32         %r60, %r60, 1;
    bra             L_ic;
L_ic_end:
    // Store result (only active)
    @!%p0 bra       RET;
    st.global.f32   [%rd21], %f0;
RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convt3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        if groups != 1:
            raise NotImplementedError("groups != 1 not supported")
        if stride != (1, 1, 1):
            raise NotImplementedError("Only stride=(1,1,1) supported")
        if padding != (0, 0, 0):
            raise NotImplementedError("Only padding=(0,0,0) supported")
        if output_padding != (0, 0, 0):
            raise NotImplementedError("Only output_padding=(0,0,0) supported")
        if bias:
            raise NotImplementedError("bias=True not supported")
        kd, kh, kw = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = (kd, kh, kw)
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = None
        # Weight layout matches nn.ConvTranspose3d: (in_channels, out_channels, kd, kh, kw)
        w = torch.empty(in_channels, out_channels, kd, kh, kw)
        nn.init.kaiming_uniform_(w, a=5 ** 0.5)
        self.weight = nn.Parameter(w)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
            raise NotImplementedError("Only float32 supported")
        if not x.is_contiguous():
            x = x.contiguous()
        N, Cin, Din, Hin, Win = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"

        kd, kh, kw = self.kernel_size
        # For stride=1, padding=0, output_padding=0, dilation=1:
        Dout = Din + kd - 1
        Hout = Hin + kh - 1
        Wout = Win + kw - 1

        out = torch.empty((N, self.out_channels, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        # Ensure weight is on the same device and contiguous
        w = self.weight
        if not w.is_contiguous():
            w = w.contiguous()
        if w.device != x.device:
            w = w.to(device=x.device)

        total = N * self.out_channels * Dout * Hout * Wout
        spatial = Dout * Hout * Wout
        block_x = min(256, spatial)
        grid_x = (total + block_x - 1) // block_x
        module = _get_ptx_module()
        smem_bytes = 2 * kd * kh * kw * 4
        module.launch(
            "convt3d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, w, out,
                i32(N), i32(Cin), i32(self.out_channels),
                i32(Din), i32(Hin), i32(Win),
                i32(kd), i32(kh), i32(kw),
                i32(Dout), i32(Hout), i32(Wout),
            ],
            shared_memory=smem_bytes,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
